package com.bananalab.lite;
import android.app.*;import android.content.*;import android.os.*;import java.util.*;import java.io.*;import org.json.*;
public final class Native63Instrumentation extends Instrumentation{
 void check(boolean b,String s){if(!b)throw new AssertionError(s);}
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}
 BananaEngine.Result run(Context c,String s)throws Exception{return BananaEngine.run(c,s,new ArrayList<String[]>(),"",true,OwnBrain.load(c));}
 @Override public void onStart(){Bundle out=new Bundle();try{Context c=getTargetContext();DurableCode.awaitReady();KnowledgeNotebook.prefs(c).edit().clear().commit();MobileCore.prefs(c).edit().remove("style").commit();ConversationFeedback.prefs(c).edit().clear().commit();
 run(c,"crea a Fito un zorro");String before=MobileCore.scene(c).json().toString();BananaEngine.Result feedback=run(c,"no me entendiste");check(feedback.mode.equals("correccion_chat")&&!feedback.changed&&feedback.studioId.isEmpty()&&!feedback.importReference&&before.equals(MobileCore.scene(c).json().toString()),"chat correction never becomes scene edit/editor");
 run(c,"aprende que el asterion es un motor de prueba.");run(c,"que es el asterion");check(run(c,"no, el asterion es un reloj de prueba.").text.contains("reloj de prueba"),"natural factual correction learned");String normal=run(c,"que es el asterion").text;check(normal.indexOf("reloj de prueba")<normal.indexOf("motor de prueba"),"corrected source ranked first");
 run(c,"no me respondas tan largo");String brief=run(c,"que es el asterion").text;check(brief.length()<normal.length()&&brief.contains("reloj de prueba")&&!brief.contains("motor de prueba"),"reply actually changes to brief and uses correction");
 StringBuilder large=new StringBuilder();for(int i=0;i<4000;i++)large.append("Contenido de archivo para una prueba de lectura extensa. ");for(int i=0;i<3;i++)KnowledgeNotebook.remember(c,"Archivo extenso "+i,large.toString()+(i==0?" La tardina es una sustancia ficticia que guarda la clave Zeta889.":" Este archivo no contiene el dato solicitado."),"https://example.com/archivo"+i,"web");check(run(c,"que es la tardina").text.contains("Zeta889"),"fact after old12000 cap used by chat");
 File backup=DurableCode.exportBackup(c);check(backup.length()>500000&&backup.length()<DurableCode.PORTABLE_LIMIT,"backup beyond old reader limit");JSONObject portable;try(InputStream in=new FileInputStream(backup)){portable=new JSONObject(new String(OnDeviceJava.bytes(in,DurableCode.PORTABLE_LIMIT),"UTF-8"));}check(portable.getJSONObject("experience").getString("style").equals("breve"),"style included in backup");KnowledgeNotebook.prefs(c).edit().clear().commit();MobileCore.prefs(c).edit().remove("style").commit();DurableCode.importBackup(c,portable);check(MobileCore.prefs(c).getString("style","").equals("breve")&&run(c,"que es la tardina").text.contains("Zeta889"),"large backup restores sources/style and derived knowledge");
 out.putString("stream","PASS NATIVE63 correction leaves scene/editor untouched, factual correction changes subsequent answers, brief preference changes response, fact beyond12k and >500k backup export/import restores knowledge/style.\n");finish(Activity.RESULT_OK,out);
 }catch(Throwable e){StringWriter s=new StringWriter();e.printStackTrace(new PrintWriter(s));out.putString("stream","FAIL "+s);finish(Activity.RESULT_CANCELED,out);}}
}
